let select_opthalmology_lab_tests = function (frm) {
    var d = new frappe.ui.Dialog({
        title: "Select Lab Tests",
        fields: [
            { fieldname: 'ht', fieldtype: 'HTML' },
        ],
        primary_action_label: "Update",
        primary_action: function () {
            let selected = [];
            d.$wrapper.find("input[name='lab']:checked").each(function () {
                selected.push($(this).val());
            });

            frappe.model.clear_table(cur_frm.doc, "lab_test_prescription");

            selected.forEach(lab => {
                let row = frappe.model.add_child(cur_frm.doc, "Lab Prescription", "lab_test_prescription");
                row.lab_test_code = lab;
            });

            refresh_field("lab_test_prescription");
            d.hide();
        }
    });

    // ✅ Destroy dialog DOM on close
    d.$wrapper.on('hidden.bs.modal', function () {
        d.$wrapper.find('.modal-body').html('');
        d = null;
    });

    frappe.db.get_list("Lab Test Template", {
        fields: ["name", "lab_test_name", "is_ophthalmology_package"],
        filters: {
            is_billable: 1,
            disabled: 0,
            is_ophthalmology_package: 1
        },
        limit: 500,
        order_by: "lab_test_name"
    }).then((records) => {

        // ✅ Always fresh from doc on every open
        let selectedlabs = (cur_frm.doc.lab_test_prescription || []).map(r => r.lab_test_code);
        let checkAll = selectedlabs.length === 0;

        let rows = records.map((test) => {
            let isSelected = checkAll || selectedlabs.includes(test.name);
            return `
                <label style="
                    display: flex;
                    align-items: center;
                    gap: 10px;
                    padding: 8px 10px;
                    border-bottom: 1px solid #f0f0f0;
                    cursor: pointer;
                    font-size: 13px;
                    color: #333;
                ">
                    <input
                        type="checkbox"
                        name="lab"
                        value="${test.name}"
                        ${isSelected ? "checked" : ""}
                        style="
                            width: 16px;
                            height: 16px;
                            min-width: 16px;
                            accent-color: #5e64ff;
                            cursor: pointer;
                        "
                    >
                    <span>${test.lab_test_name}</span>
                    ${isSelected && !checkAll ? '<span style="color: #28a745; font-size: 11px; margin-left: auto;">✓ Added</span>' : ""}
                </label>
            `;
        }).join("");

        let container = `
            <div style="max-height: 400px; overflow-y: auto; margin: -15px;">
                ${rows || "<p style='padding:16px'>No lab tests available</p>"}
            </div>
        `;

        // ✅ Clear first then set fresh HTML
        d.fields_dict.ht.$wrapper.html('');
        d.fields_dict.ht.$wrapper.html(container);
        d.$wrapper.find(".modal-dialog").css({ "max-width": "400px", "width": "400px" });
        d.show();
    });
};

