/* =============================== LOAD BALANCE ================================ */
function loadBalance(frm) {
    frappe.call({
        method: 'his.his.doctype.daily_closing.daily_closing.get_balance',
        args: {
            date: frm.doc.date
        },
        callback(r) {
            console.log("Balance Response:", r);

            if (r.message && Array.isArray(r.message)) {
                frm.set_value("account", r.message[1] || "");
                frm.set_value("balance", r.message[0] || 0);
            } else {
                frm.set_value("account", "");
                frm.set_value("balance", 0);
                frappe.msgprint("No balance found for selected date");
            }
        }
    });
}


