frappe.ui.form.on('Forecast Form Income', {
    qty: function(frm, cdt, cdn) {
        calculate_income_row(frm, cdt, cdn);
    },
    price: function(frm, cdt, cdn) {
        calculate_income_row(frm, cdt, cdn);
    },
    service_income: function(frm, cdt, cdn) {
        calculate_income_row(frm, cdt, cdn);
    },
    revenue: function(frm, cdt, cdn) {
        let row = locals[cdt][cdn];
        if (is_other_income(row)) {
            calculate_income_percentages(frm);
        }
    },
    forecast_form_income_add: function(frm, cdt, cdn) {
        calculate_income_row(frm, cdt, cdn);
    },
    forecast_form_income_remove: function(frm) {
        calculate_income_percentages(frm);
    }
});

function is_other_income(row) {
    let label = (row.service_income || '').trim().toLowerCase();
    return label === 'other income';
}

function calculate_income_row(frm, cdt, cdn) {
    let row = locals[cdt][cdn];

    if (is_other_income(row)) {
        row.qty_per_month = 1;
        row.revenue = flt(row.price) * flt(row.qty_per_month);
        // leave row.revenue as whatever the user typed manually
    } else {
        row.qty_per_month = flt(row.qty) * 26;
        row.revenue = flt(row.price) * flt(row.qty_per_month);
    }

    frm.refresh_field('income'); // replace 'income' with your actual child table fieldname
    calculate_income_percentages(frm);
}

function calculate_income_percentages(frm) {
    let total_revenue = 0;
    (frm.doc.income || []).forEach(row => {
        total_revenue += flt(row.revenue);
    });
    (frm.doc.income || []).forEach(row => {
        row.revenue_percentage = total_revenue
            ? flt(row.revenue) / total_revenue * 100
            : 0;
    });
    frm.refresh_field('income');
    frm.set_value('total_income', total_revenue);
    calculate_profit_or_loss(frm);
}

