// Client Script
// DocType: Daily Cash Closer
// Apply To: Form   |   Enabled: Yes

const DCC_COLLECTION_TABLE = "daily_collection_detail";
const DCC_PAYMENT_TABLE = "daily_payment_mode_detail";
const DCC_ACCOUNT_TABLE = "account_balance_detail";

function dcc_total(frm, table_fieldname) {
    return (frm.doc[table_fieldname] || []).reduce(
        (running, row) => running + flt(row.amount),
        0
    );
}

// Row-level variance for the Account Balance Detail grid:
//   varriance = amount - erp_amount
function dcc_account_row_variance(frm, cdt, cdn) {
    const row = locals[cdt][cdn];
    frappe.model.set_value(
        cdt,
        cdn,
        "varriance",
        flt(row.amount) - flt(row.erp_amount)
    );
}

function dcc_calculate(frm) {
    const collection = dcc_total(frm, DCC_COLLECTION_TABLE);
    const payments = dcc_total(frm, DCC_PAYMENT_TABLE);
    const accounts = dcc_total(frm, DCC_ACCOUNT_TABLE);

    frm.set_value("total_collection", collection);
    frm.set_value("total_payments", payments);
    frm.set_value("total_account_balance", accounts);

    // variance = what came in minus what went out.
    // Computed BEFORE the expected_closing_cash guard so it always runs.
    if (frm.fields_dict.variance) {
        frm.set_value("variance", collection - payments);
    }

    // The block below stays dormant until you add the reconciliation fields.
    // Nothing breaks if they don't exist yet.
    if (!frm.fields_dict.expected_closing_cash) return;

    const expected = flt(frm.doc.opening_cash_balance) + collection - payments;
    frm.set_value("expected_closing_cash", expected);

    // Separate field for the physical cash-count difference, so it does not
    // collide with `variance`. Safe no-op until you create it.
    if (frm.fields_dict.cash_count_difference) {
        frm.set_value(
            "cash_count_difference",
            flt(frm.doc.actual_cash_counted) - expected
        );
    }
}

function dcc_filter_accounts(frm) {
    frm.set_query("account", DCC_PAYMENT_TABLE, function (doc) {
        const filters = {
            is_group: 0,
            account_type: ["in", ["Bank", "Cash"]],
        };
        if (doc.company) filters.company = doc.company;
        return { filters: filters };
    });
}

function dcc_show_variance(frm) {
    if (!frm.fields_dict.variance || frm.is_new()) return;

    const variance = flt(frm.doc.variance);

    if (variance > 0.005) {
        frm.dashboard.set_headline_alert(
            __("Net inflow of {0}", [format_currency(variance)]),
            "green"
        );
    } else if (variance < -0.005) {
        frm.dashboard.set_headline_alert(
            __("Net outflow of {0}", [format_currency(Math.abs(variance))]),
            "orange"
        );
    } else {
        frm.dashboard.set_headline_alert(
            __("Collections equal payments"),
            "blue"
        );
    }
}

frappe.ui.form.on("Daily Cash Closer", {
    setup(frm) {
        dcc_filter_accounts(frm);
    },



    refresh(frm) {
        dcc_calculate(frm);
        dcc_show_variance(frm);
    },

    opening_cash_balance(frm) {
        dcc_calculate(frm);
    },

    actual_cash_counted(frm) {
        dcc_calculate(frm);
    },

    daily_collection_detail_add(frm) {
        dcc_calculate(frm);
    },

    daily_collection_detail_remove(frm) {
        dcc_calculate(frm);
    },

    daily_payment_mode_detail_add(frm) {
        dcc_calculate(frm);
    },

    daily_payment_mode_detail_remove(frm) {
        dcc_calculate(frm);
    },

    validate(frm) {
        // Strip rows the cashier added but never filled — otherwise the
        // mandatory Description / Account fields block the save.
        frm.doc[DCC_COLLECTION_TABLE] = (frm.doc[DCC_COLLECTION_TABLE] || [])
            .filter((row) => row.description || flt(row.amount));
        frm.doc[DCC_PAYMENT_TABLE] = (frm.doc[DCC_PAYMENT_TABLE] || [])
            .filter((row) => row.account || flt(row.amount));

        frm.refresh_field(DCC_COLLECTION_TABLE);
        frm.refresh_field(DCC_PAYMENT_TABLE);

        dcc_calculate(frm);

        // NOTE: the old remarks check keyed off `variance` being non-zero.
        // With variance now meaning collection − payments, that is non-zero on
        // almost every normal day, so it is keyed off the cash-count
        // difference instead. Delete this block if you don't want it.
        if (
            frm.fields_dict.cash_count_difference &&
            Math.abs(flt(frm.doc.cash_count_difference)) > 0.005 &&
            !(frm.doc.remarks || "").trim()
        ) {
            frappe.throw(__("Please enter Remarks explaining the variance."));
        }
    },
});

// Recalculate as soon as an amount is typed in either grid.
frappe.ui.form.on("Daily Collection Detail", {
    amount(frm) {
        dcc_calculate(frm);
    },
});

frappe.ui.form.on("Daily Payment Mode Detail", {
