function get_items_field(frm) {
    const df = frm.meta.fields.find(
        f => f.fieldtype === "Table" && f.options === "Custom Purchase Order Item"
    );
    if (!df) {
        console.error("No Table field pointing to Custom Purchase Order Item found.");
        return null;
    }
    return df.fieldname;
}

function calculate_amount(frm, cdt, cdn) {
    const row = locals[cdt][cdn];
    frappe.model.set_value(cdt, cdn, "amount", flt(row.qty) * flt(row.rate));
}

function calculate_total(frm) {
    const fieldname = get_items_field(frm);
    if (!fieldname) return;

    let total = 0;
    (frm.doc[fieldname] || []).forEach(row => {
        total += flt(row.amount);
    });

    console.log("Table field:", fieldname, "| Rows:", (frm.doc[fieldname] || []).length, "| Total:", total);

    if (!frm.fields_dict.total) {
        console.error("No field named 'total' exists on Custom Purchase Order.");
        return;
    }
    frm.set_value("total", total);
    frm.refresh_field("total");
}

