const ESC_STAGES = [
    [1, "First"],
    [2, "Second"],
    [3, "Third"],
    [4, "Final"],
];

// ---------------------------------------------------------------------
// MANUAL ESCALATION MATRIX
// No "Escalation Rule" doctype is used. Edit this array directly to
// change who gets notified, at which stage, for each severity level.
// Source: Incident Reporting Database requirements doc — Automatic
// Escalation Matrix section.
//
//   severity_level   -> must match the value stored in the
//                        "severity_level" field on Hospital Incident
//                        (e.g. "Level 1" ... "Level 5")
//   stage             -> 1=First, 2=Second, 3=Third, 4=Final
//                        (matches ESC_STAGES above)
//   contact_name      -> display name shown in the cell. Add multiple
//                        rows with the same severity_level+stage to
//                        stack several contacts in one cell.
//   delay_minutes     -> minutes after the previous stage before this
//                        stage fires (0 = immediate). Not specified
//                        per-stage in the requirements doc yet, so
//                        left at 0 — fill in once timings are agreed.
//   note              -> optional free-text condition shown under the
//                        contact(s), e.g. "if repeated", "if required"
// ---------------------------------------------------------------------
const MATRIX_RULES = [
    // Level 1 — No harm (Near miss)
    { severity_level: "Level 1", stage: 1, contact_name: "Supervisor", delay_minutes: 0 },
    { severity_level: "Level 1", stage: 2, contact_name: "Department Head", delay_minutes: 0 },
    { severity_level: "Level 1", stage: 3, contact_name: "Quality Coordinator", delay_minutes: 0, note: "if repeated" },

    // Level 2 — Mild harm
    { severity_level: "Level 2", stage: 1, contact_name: "Supervisor", delay_minutes: 0 },
    { severity_level: "Level 2", stage: 2, contact_name: "Department Head", delay_minutes: 0 },
    { severity_level: "Level 2", stage: 3, contact_name: "Quality Coordinator", delay_minutes: 0, note: "if required" },

    // Level 3 — Moderate harm
    { severity_level: "Level 3", stage: 1, contact_name: "Supervisor", delay_minutes: 0 },
    { severity_level: "Level 3", stage: 2, contact_name: "Department Head", delay_minutes: 0 },
    { severity_level: "Level 3", stage: 3, contact_name: "Quality Coordinator", delay_minutes: 0 },
    { severity_level: "Level 3", stage: 4, contact_name: "Medical Director", delay_minutes: 0 },

    // Level 4 — Severe harm
    { severity_level: "Level 4", stage: 1, contact_name: "Supervisor", delay_minutes: 0 },
    { severity_level: "Level 4", stage: 2, contact_name: "Department Head", delay_minutes: 0 },
    { severity_level: "Level 4", stage: 3, contact_name: "Quality Coordinator", delay_minutes: 0 },
    { severity_level: "Level 4", stage: 3, contact_name: "Medical Director", delay_minutes: 0 },
    { severity_level: "Level 4", stage: 4, contact_name: "CEO", delay_minutes: 0 },

    // Level 5 — Sentinel event
    { severity_level: "Level 5", stage: 1, contact_name: "Emergency Team", delay_minutes: 0 },
    { severity_level: "Level 5", stage: 2, contact_name: "Department Head", delay_minutes: 0 },
    { severity_level: "Level 5", stage: 2, contact_name: "Quality Coordinator", delay_minutes: 0 },
    { severity_level: "Level 5", stage: 2, contact_name: "Medical Director", delay_minutes: 0 },
    { severity_level: "Level 5", stage: 3, contact_name: "CEO", delay_minutes: 0 },
    { severity_level: "Level 5", stage: 4, contact_name: "Incident Command Team", delay_minutes: 0 },
];

function esc_tone(level_name) {
    const m = String(level_name).match(/(\d+)/);
    const n = m ? parseInt(m[1], 10) : 0;
    if (n <= 2) return "green";
    if (n === 3) return "orange";
    return "red";
}

function esc_html(s) {
    return frappe.utils.escape_html(String(s == null ? "" : s));
}

function render_matrix(frm) {
    const field = frm.fields_dict.matrix_html;
    if (!field) return;
    const $w = field.$wrapper;

    inject_css();
    // No DB call needed anymore — build straight from the manual list.
    $w.html(build_matrix(MATRIX_RULES, frm.doc.severity_level));
}

function build_matrix(rows, current_level) {
    if (!rows || !rows.length) {
        return '<div class="esc-mx-loading">No escalation rules defined yet.</div>';
    }

    // group: level -> stage -> [rules]
    const levels = {};
    rows.forEach((r) => {
        if (!levels[r.severity_level]) levels[r.severity_level] = {};
        const s = levels[r.severity_level];
        if (!s[r.stage]) s[r.stage] = [];
        s[r.stage].push(r);
    });

    const names = Object.keys(levels).sort();

    const body = names
        .map((lvl) => {
            const stages = levels[lvl];
            const is_current = lvl === current_level;

            const cells = ESC_STAGES.map(([num]) => {
                const list = stages[num];
                if (!list || !list.length) {
                    return '<td><span class="esc-mx-dash">&mdash;</span></td>';
                }

                const who = list
                    .map((r) => esc_html(r.contact_name))
                    .join("<br>");

                const delay = list[0].delay_minutes || 0;
                const delay_txt =
                    delay > 0
                        ? `<div class="esc-mx-meta">+${fmt_delay(delay)}</div>`
                        : "";

                const note = list.find((r) => r.note);
                const cond = note
                    ? `<div class="esc-mx-cond">${esc_html(note.note)}</div>`
                    : "";

                return `<td>${who}${cond}${delay_txt}</td>`;
            }).join("");

            return `<tr class="${is_current ? "esc-mx-current" : ""}">
                <td><span class="esc-mx-lv esc-mx-${esc_tone(lvl)}">${esc_html(
                short_level(lvl)
            )}</span></td>${cells}</tr>`;
        })
        .join("");

    const head = ESC_STAGES.map(([, label]) => `<th>${label}</th>`).join("");

    return `<div class="esc-mx">
        <h5>Automatic escalation matrix</h5>
        <p class="esc-mx-sub">Each stage fires only if the previous one is not acknowledged in time.</p>
        <div class="esc-mx-scroll">
          <table>
            <thead><tr><th style="width:80px">Level</th>${head}</tr></thead>
            <tbody>${body}</tbody>
          </table>
        </div>

      </div>`;
}

function short_level(name) {
    const m = String(name).match(/Level\s*(\d+)/i);
    return m ? "Level " + m[1] : name;
}

function fmt_delay(mins) {
    if (mins < 60) return mins + "m";
    if (mins < 1440) return Math.round(mins / 60) + "h";
    return Math.round(mins / 1440) + "d";
}

function inject_css() {
    if (document.getElementById("esc-mx-css")) return;
    const style = document.createElement("style");
    style.id = "esc-mx-css";
    style.textContent = `
