.esc-mx th{text-align:left;padding:0 8px 8px 0;font-size:11px;font-weight:600;
 letter-spacing:.03em;text-transform:uppercase;color:var(--text-muted)}
.esc-mx td{padding:9px 8px;vertical-align:top;color:var(--text-color);
 border-top:1px solid var(--border-color);line-height:1.45}
.esc-mx td:first-child,.esc-mx th:first-child{padding-left:0}
.esc-mx td:last-child,.esc-mx th:last-child{padding-right:0}
.esc-mx-lv{display:inline-block;padding:2px 9px;border-radius:10px;
 font-size:11px;font-weight:600;white-space:nowrap}
