frappe.ui.form.on('OT Schedules', {
    async patient(frm) {

        // Field on VA Examination that links to the patient
        const VA_PATIENT_FIELD = 'patient';

        // Lab Test Template name -> fieldname on VA Examination
        const VA_EXAM_FIELDS = {
            RE_VA: 'va',
            LE_VA: 'va1',
            RE_IOP: 'iop_right',
            LE_IOP: 'iop_left'
        };

        // Fieldname on OT Schedules -> fieldname on VA Examination
        const OT_FORM_FIELDS = {
            re_va: 'va',
            le_va: 'va1',
            re_iop: 'iop_right',
            le_iop: 'iop_left'
        };

        // 1) Always reset first, even when the patient is cleared
        frm.clear_table('lab_result_child');
        frm.refresh_field('lab_result_child');
        for (const formField of Object.keys(OT_FORM_FIELDS)) {
            await frm.set_value(formField, '');
        }

        if (!frm.doc.patient) return;

        const currentPatient = frm.doc.patient;

        try {
            const vaFilters = { docstatus: ['!=', 2] };
            vaFilters[VA_PATIENT_FIELD] = currentPatient;

            const [latestLab, latestVA, templates] = await Promise.all([
                frappe.db.get_list('Lab Result', {
                    fields: ['name'],
                    filters: { patient: currentPatient, docstatus: ['!=', 2] },
                    order_by: 'creation desc',
                    limit: 1
                }),
                frappe.db.get_list('VA Examination', {
                    fields: ['name'],
                    filters: vaFilters,
                    order_by: 'creation desc',
                    limit: 1
                }),
                frappe.db.get_list('Lab Test Template', {
                    fields: ['name', 'lab_test_name', 'lab_test_normal_range'],
                    filters: {
                        is_billable: 1,
                        disabled: 0,
                        is_ophthalmology_package: 1,
                        name: ['!=', 'CBC']
                    },
                    order_by: 'name asc',
                    limit: 500,
                    limit_page_length: 500
                })
            ]);

            const [lab, vaExam] = await Promise.all([
                latestLab.length ? frappe.db.get_doc('Lab Result', latestLab[0].name) : null,
                latestVA.length ? frappe.db.get_doc('VA Examination', latestVA[0].name) : null
            ]);

            // Patient changed while loading -> discard this result
            if (frm.doc.patient !== currentPatient) return;

            console.log('[OT] VA Examination doc:', vaExam);

            // Previous results from Lab Result
            const previous = {};
            ((lab && lab.normal_test_items) || []).forEach(r => {
                const key = r.template || r.lab_test_name || r.test;
                if (key) previous[key] = r.result_value;
            });

            // Fill the child table
            frm.clear_table('lab_result_child');
            templates.forEach(t => {
                const row = frm.add_child('lab_result_child');
                row.test = t.name;
                row.normal_range = t.lab_test_normal_range || '';

                if (VA_EXAM_FIELDS[t.name]) {
                    row.result = (vaExam && vaExam[VA_EXAM_FIELDS[t.name]]) || '';
                } else {
                    row.result = previous[t.name] || previous[t.lab_test_name] || '';
                }
            });
            frm.refresh_field('lab_result_child');

            // Fill the fields on the OT Schedules form (only if this patient has a VA Examination)
            if (vaExam) {
                for (const [formField, examField] of Object.entries(OT_FORM_FIELDS)) {
                    if (vaExam[examField]) {
                        await frm.set_value(formField, vaExam[examField]);
                    }
                }
            }
        } catch (e) {
            console.error('[OT] error:', e);
            frappe.msgprint({ title: 'Error', message: e.message || String(e), indicator: 'red' });
        }
    }
});

// ============================================================================
// Gonioscopy Quadrant Diagram (X-divided circle + input per quadrant)
// Frappe/ERPNext Client Script
// ----------------------------------------------------------------------------
// SETUP REQUIRED (Customize Form / Custom Field, on your DocType):
//   1. Field "gonioscopy_html"  → Field Type: HTML
//        Place it where the "GONIOSCOPY" section currently sits.
//   2. Field "gonioscopy_data"  → Field Type: Long Text (or Code), Hidden
//        This is what actually persists the structured result on save.
//
// Then: Setup > Client Script > New
//   DocType: <your doctype, e.g. "Glaucoma Clinical Record">
//   Script Type: Client
//   Paste this whole file.
//
// Replace DOCTYPE_NAME below with your actual DocType name.
// ============================================================================

const DOCTYPE_NAME = "GLAUCOMA CLINICAL RECORD";
const HTML_FIELD = "gonioscopy_html";
const DATA_FIELD = "gonioscopy_data";

frappe.ui.form.on(DOCTYPE_NAME, {
	refresh: function (frm) {
		render_gonioscopy_widget(frm);
	},
});

// Structure options shown in each quadrant's dropdown, with a colour for quick visual scan
const OPTIONS = [
	{ value: "", label: "–", color: "#ffffff" },
	{ value: "SL", label: "SL", color: "#bfdbfe" },
	{ value: "TM", label: "TM", color: "#a7f3d0" },
	{ value: "SS", label: "SS", color: "#fde68a" },
	{ value: "CB", label: "CB", color: "#fecaca" },
	{ value: "IP+", label: "IP present", color: "#e9d5ff" },
];

function quadrantsForEye(eye) {
	// angle: 0=right, 90=down, 180=left, 270=up (SVG, clockwise)
	const nasalOnRight = eye === "OD";
	return [
		{ key: "S", label: "Superior", angle: 270 },
		{ key: "I", label: "Inferior", angle: 90 },
		{ key: nasalOnRight ? "N" : "T", label: nasalOnRight ? "Nasal" : "Temporal", angle: 0 },
		{ key: nasalOnRight ? "T" : "N", label: nasalOnRight ? "Temporal" : "Nasal", angle: 180 },
	];
}

function polar(cx, cy, r, angleDeg) {
	const a = (angleDeg * Math.PI) / 180;
	return { x: cx + r * Math.cos(a), y: cy + r * Math.sin(a) };
}

function ensureStyles() {
	if (document.getElementById("gonio-quad-style")) return;
	const style = document.createElement("style");
	style.id = "gonio-quad-style";
	style.innerHTML = `
		.gonio-wrap2 { display:flex; gap:36px; flex-wrap:wrap; padding:10px 0; }
		.gonio-eye-block2 { text-align:center; width:300px; }
		.gonio-title2 { font-weight:700; font-size:18px; margin-bottom:6px; }
		.gonio-circle-holder { position:relative; width:300px; height:300px; margin:0 auto; }
		.gonio-circle-holder svg { position:absolute; top:0; left:0; }
		.gonio-input2 {
			position:absolute; width:64px; height:26px; text-align:center;
			border:1px solid #999; border-radius:4px; font-size:12px; font-weight:600;
			transform:translate(-50%,-50%); cursor:pointer;
		}
		.gonio-quad-label2 { font-size:11px; fill:#666; }
		.gonio-summary2 { font-size:12px; color:#333; margin-top:10px; min-height:16px; }
		.gonio-legend2 { display:flex; gap:10px; flex-wrap:wrap; margin-top:10px; font-size:12px; justify-content:center; }
		.gonio-legend2 span { display:inline-flex; align-items:center; gap:4px; }
		.gonio-legend2 i { width:10px; height:10px; display:inline-block; border-radius:2px; border:1px solid #bbb; }
		.gonio-reset2 { font-size:11px; margin-top:6px; cursor:pointer; color:#2563eb; text-decoration:underline; background:none; border:none; }
	`;
	document.head.appendChild(style);
}

function render_gonioscopy_widget(frm) {
	if (!frm.fields_dict[HTML_FIELD]) return; // field not set up yet
	ensureStyles();

	const $wrapper = $(frm.fields_dict[HTML_FIELD].$wrapper);
	$wrapper.empty();

	let state = { OD: {}, OS: {} };
	try {
		if (frm.doc[DATA_FIELD]) state = JSON.parse(frm.doc[DATA_FIELD]);
	} catch (e) {
		state = { OD: {}, OS: {} };
	}

	const $container = $('<div class="gonio-wrap2"></div>').appendTo($wrapper);

	["OD", "OS"].forEach((eye) => {
		const $block = $('<div class="gonio-eye-block2"></div>').appendTo($container);
		$(`<div class="gonio-title2">Gonioscopy – ${eye}</div>`).appendTo($block);

		const $holder = $('<div class="gonio-circle-holder"></div>').appendTo($block);
		buildCircle($holder[0], eye, state[eye]);

		const $summary = $('<div class="gonio-summary2"></div>').appendTo($block);
		updateSummary($summary, state[eye]);

		$holder.find(".gonio-input2").on("change", function () {
			const quad = $(this).data("quad");
			state[eye][quad] = this.value;
			$(this).css("background", colorFor(this.value));
			persist(frm, state);
			updateSummary($summary, state[eye]);
		});

		$(`<button class="gonio-reset2" type="button">Clear ${eye}</button>`)
			.appendTo($block)
			.on("click", () => {
				state[eye] = {};
				persist(frm, state);
				updateSummary($summary, state[eye]);
				$holder.find(".gonio-input2").each(function () {
					this.value = "";
					$(this).css("background", "#ffffff");
				});
			});
	});

	const $legend = $('<div class="gonio-legend2"></div>').appendTo($wrapper);
	OPTIONS.filter((o) => o.value).forEach((o) => {
		$(`<span><i style="background:${o.color}"></i>${o.label}</span>`).appendTo($legend);
	});
}

function colorFor(value) {
	const opt = OPTIONS.find((o) => o.value === value);
	return opt ? opt.color : "#ffffff";
}

function buildCircle(holderEl, eye, quadState) {
	const cx = 150, cy = 150, r = 140;
	const svgNS = "http://www.w3.org/2000/svg";
	const svg = document.createElementNS(svgNS, "svg");
	svg.setAttribute("viewBox", "0 0 300 300");
	svg.setAttribute("width", "300");
	svg.setAttribute("height", "300");

	// outer circle
	const circle = document.createElementNS(svgNS, "circle");
	circle.setAttribute("cx", cx);
	circle.setAttribute("cy", cy);
	circle.setAttribute("r", r);
	circle.setAttribute("fill", "none");
	circle.setAttribute("stroke", "#111");
	circle.setAttribute("stroke-width", "3");
	svg.appendChild(circle);

	// X divider (diagonals at 45/135/225/315, corner to corner)
	[45, 135].forEach((a) => {
		const p1 = polar(cx, cy, r, a);
		const p2 = polar(cx, cy, r, a + 180);
		const line = document.createElementNS(svgNS, "line");
		line.setAttribute("x1", p1.x);
		line.setAttribute("y1", p1.y);
		line.setAttribute("x2", p2.x);
		line.setAttribute("y2", p2.y);
		line.setAttribute("stroke", "#111");
		line.setAttribute("stroke-width", "2");
		svg.appendChild(line);
	});

	holderEl.appendChild(svg);

	// quadrant labels + input dropdowns, placed at mid-radius along each cardinal bisector
	quadrantsForEye(eye).forEach((q) => {
		const labelPt = polar(cx, cy, r - 22, q.angle);
		const label = document.createElementNS(svgNS, "text");
		label.setAttribute("x", labelPt.x);
		label.setAttribute("y", labelPt.y);
		label.setAttribute("text-anchor", "middle");
		label.setAttribute("class", "gonio-quad-label2");
		label.textContent = q.label;
		svg.appendChild(label);

		const inputPt = polar(cx, cy, 75, q.angle);
		const select = document.createElement("select");
		select.className = "gonio-input2";
		select.dataset.quad = q.key;
		select.style.left = inputPt.x + "px";
		select.style.top = inputPt.y + "px";
		OPTIONS.forEach((o) => {
			const opt = document.createElement("option");
			opt.value = o.value;
			opt.textContent = o.label;
			select.appendChild(opt);
		});
		const current = quadState[q.key] || "";
		select.value = current;
		select.style.background = colorFor(current);
		holderEl.appendChild(select);
	});
}

function updateSummary($el, quadState) {
	const order = ["S", "N", "I", "T"];
	const parts = order.filter((q) => quadState[q]).map((q) => `${q}:${quadState[q]}`);
	$el.text(parts.length ? parts.join("  ") : "No findings recorded yet");
}

function persist(frm, state) {
	frm.set_value(DATA_FIELD, JSON.stringify(state));
	frm.dirty();
}

