    }

    function allowed_types() {
        const roles = frappe.user_roles || [];
        const is_hr_manager = roles.includes("HR Manager");

        return Object.keys(QUESTIONS).filter(type => {
            if (type === "Doctor and Nurse Availability") {
                return is_hr_manager;
            }
            return true;
        });
    }

    function check_fields(frm) {
        for (const field of ["user", "date", "checklist_type", TABLE]) {
            if (!frm.fields_dict[field]) {
                frappe.throw(
                    `Field "${field}" kama jiro Main DocType-ka. ` +
                    "Fieldnames-ka u waafaji tilmaamaha."
                );
            }
        }

        const grid = frm.fields_dict[TABLE].grid;
        const child_meta = frappe.get_meta(grid.doctype);

        for (const field of ["question", "answer"]) {
            if (!(child_meta.fields || []).some(
                df => df.fieldname === field
            )) {
                frappe.throw(
                    `Field "${field}" kama jiro Child DocType-ka.`
                );
            }
        }
    }

    function lock_questions(frm) {
        const grid = frm.fields_dict[TABLE].grid;

        frm.set_df_property(TABLE, "cannot_add_rows", true);
        frm.set_df_property(TABLE, "cannot_delete_rows", true);

        grid.update_docfield_property("question", "read_only", 1);
        grid.update_docfield_property("answer", "options", "\nYes\nNo\nN/A");
        grid.refresh();

        // Checklist Type waa la beddeli karaa inta document-ku Draft yahay.
        frm.set_df_property("checklist_type", "read_only", 0);
    }

    function load_questions(frm, replace_existing = false) {
        const type = frm.doc.checklist_type;
        if (!type && !replace_existing) return;
        if (Number(frm.doc.docstatus || 0) !== 0) return;
        if (!type && replace_existing) {
            frm.clear_table(TABLE);
            frm.refresh_field(TABLE);
            frm.dirty();
            return;
        }

        if (!allowed_types().includes(type)) {
            frappe.throw("Checklist-kan laguma qoondeyn.");
        }

        // Onload wuxuu ilaaliyaa rows-ka jira.
        // Onchange wuxuu tirtiraa rows-ka iyo jawaabaha hore.
        if (!replace_existing) {
            if (!frm.is_new()) return;
            if ((frm.doc[TABLE] || []).length) return;
        } else {
            frm.clear_table(TABLE);
        }

        QUESTIONS[type].forEach(question => {
            frm.add_child(TABLE, {
                question: question,
                answer: ""
            });
        });

        frm.refresh_field(TABLE);
        frm.dirty();
        lock_questions(frm);
    }

    frappe.ui.form.on(DOCTYPE, {
        async onload(frm) {
            check_fields(frm);

            const allowed = allowed_types();

            frm.set_df_property(
                "checklist_type",
                "options",
                ["", ...allowed].join("\n")
            );

            if (frm.is_new()) {
                await frm.set_value("user", frappe.session.user);

                if (!frm.doc.date) {
                    await frm.set_value(
                        "date",
                        frappe.datetime.get_today()
                    );
                }
            }

            if (!allowed.length) {
                frm.disable_save();
                frappe.msgprint(
                    "User-kan checklist loo oggol yahay ma jiro."
                );
                return;
            }

            // Haddii hal checklist loo qoondeeyey, si toos ah u dooro.
            if (frm.is_new() &&
                !frm.doc.checklist_type &&
                allowed.length === 1) {
                await frm.set_value("checklist_type", allowed[0]);
            }

            load_questions(frm);
            lock_questions(frm);
        },

        refresh(frm) {
            frm.set_df_property(
                "checklist_type",
                "options",
                ["", ...allowed_types()].join("\n")
            );

            if (frm.fields_dict[TABLE]) {
                lock_questions(frm);
            }
        },

        checklist_type(frm) {
            load_questions(frm, true);
        },

        validate(frm) {
            const type = frm.doc.checklist_type;

            if (!allowed_types().includes(type)) {
                frappe.throw("Checklist-kan laguma qoondeyn.");
            }

            if (!is_admin() &&
                frm.doc.user !== frappe.session.user) {
                frappe.throw(
                    "Waxaad buuxin kartaa diiwaankaaga oo keliya."
                );
            }

            const expected = QUESTIONS[type];
            const rows = frm.doc[TABLE] || [];

            if (!expected || rows.length !== expected.length) {
                frappe.throw(
                    "Su'aalaha checklist-ku ma dhammaystirna."
                );
            }

            rows.forEach((row, index) => {
                if (row.question !== expected[index]) {
                    frappe.throw(
                        `Su'aasha row ${index + 1} waa la beddelay.`
                    );
                }

                if (!["Yes", "No", "N/A"].includes(row.answer)) {
                    frappe.throw(
                        `Ka jawaab su'aasha ${index + 1}: Yes, No ama N/A.`
                    );
                }
            });
        }
    });
})();
